#!/usr/bin/env python3
"""Render the V6 HA report from measured process results, without source identities."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'docs/proposition/analyse/v6'
r=json.loads((OUT/'ha-multimaison-resultats.json').read_text());live=json.loads((OUT/'ha-multimaison-live.json').read_text())
esc=lambda s:html.escape(str(s))
def mib(n):return f'{n/1048576:.2f}'.replace('.',',')
def table(head,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
case_rows=[]
for c in r['cases']:
 s=c['snapshot'];case_rows.append([esc(c['case']),esc(c['status']),len(s['nodes']),mib(sum(n['allocator_live_bytes'] or 0 for n in s['nodes']))+' Mio',mib(sum(n['rss_bytes'] or 0 for n in s['nodes']))+' Mio'])
css=(OUT/'index.html').read_text().split('<style>',1)[1].split('</style>',1)[0]
page='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>V6 · Haute disponibilité entre deux maisons</title><style>'''+css+'''</style><body><div class="wrap"><header class="hero"><p class="eyebrow">Moli · Complément V6 · 27 octobre2026</p><h1>Actif pour sa maison.<br>Passif pour l’autre.</h1><p class="intro">Deux serveurs portent les deux maisons, avec des rôles indépendants. Un même serveur reste actif pour sa maison pendant qu’il conserve ou reprend la copie de l’autre.</p></header><p class="note"><a href="index.html">Dossier V6</a> · <a href="modules.html">Hôtes et master</a> · <a href="ha-multimaison-resultats.json">Résultats de processus</a> · <a href="ha-multimaison-live.json">Lecture réelle des brokers HA</a> · <a href="ha-multimaison-preuves.json">Preuves et empreintes</a></p><main class="main">
<section class="section"><h2>Le scénario principal</h2>'''+table(['Serveur','Maison A','Maison B'],[['Dans A','<strong>Actif</strong>','Passif'],['Dans B','Passif','<strong>Actif</strong>']])+'''<p>L’interface affiche cette matrice, un sélecteur A/B et les copies, séquences, époques et mesures de chaque serveur. Le POC principal possède aussi son sélecteur de maison et un onglet <strong>Continuité</strong>. Les paramètres proposent aucune copie, un secours local, un secours cloud, local+cloud ou les secours croisés ; le JSON avancé autorise plusieurs dispositions.</p><p>Le service HA est un module expérimental séparé, exposé en loopback sur1416 puis sous <code>/ha/</code> par la passerelle1414. Son état rejoint le MQTT virtuel dans <code>moli-probe/ha/config</code> et <code>moli-probe/ha/state</code>. Le petit master reste séparé du code HA et du métier.</p></section>
<section class="section"><h2>Deux sources vérifiées, deux périmètres</h2><p>Les deux HA ont été consultés en lecture seule. Les registres vivants déclaraient1859 et1537entités. Une connexion MQTT native a été authentifiée sur chacun, avec abonnement aux états HA pendant quatre secondes, sans PUBLISH ni commande physique.</p>'''+table(['Source','Connexion','Messages','Retained','Messages vivants observés','Octets utiles'],[[x['id'],'Acceptée',x['messages'],x['retained'],x['observed_live'],x['payload_bytes']] for x in live['sources']])+'''<p class="caption">Zéro message vivant pendant quatre secondes ne prouve ni panne ni absence de fraîcheur. Les identifiants et mots de passe sont restés sur chaque HA ; seuls des compteurs sont enregistrés.</p><p>Les essais de crash utilisent les <strong>deux structures exportées puis anonymisées</strong>, en passant par la vraie projection du pont. Leurs effectifs peuvent différer de l’inventaire vivant, notamment à cause de la date de capture, des entités désactivées et des canaux admissibles. Ils ne sont pas présentés comme une réplique vivante des HA.</p>'''+table(['Rejeu','Entités du registre','Appareils projetés','Points','Instantané'],[[x['house'],x['entities'],x['devices'],x['points'],mib(x['snapshot_bytes'])+' Mio'] for x in r['sources']])+'''</section>
<section class="section"><h2>Ce qui a été testé</h2><p><strong>Campagne initiale : dix scénarios de processus réussis,48tests Rust et7tests d’interface HA</strong>, avec formatage et Clippy stricts. Une partie des tests Rust réutilise les contrats du broker existant. Les contrôles du POC principal, du proxy et des traductions sont documentés dans les preuves.</p><ul><li>Coupure WAN logique : A continue pour A et B pour B ; seules les copies croisées prennent du retard.</li><li>Rétablissement : reprise par la file de deltas, ou instantané complet lorsque le retard dépasse seize deltas, ou lors du retour d’un processus sans copie.</li><li>Arrêt de A puis de B : la maison voisine continue ; son serveur conserve les deux copies et peut être promu pour l’autre maison.</li><li>Ancien actif : jeton périmé rejeté ; nouvelle incarnation et époque nécessaires au retour.</li><li>Secours local automatique, cloud manuel, deux passifs et absence de passif.</li><li>Pause de calcul de3,5secondes : les baux sains restent renouvelés. Cet essai échouait avec le coordinateur sur un seul thread ; il passe avec les tâches de réseau/bail séparées du calcul.</li></ul>'''+table(['Cas','Résultat','Nœuds dans la vue','Allocations vivantes des nœuds','Somme RSS observée des nœuds'],case_rows)+'''<p class="caption">Mesures ponctuelles en debug, incluant copies JSON et ressources communes de chaque nœud ; nœud arrêté compté sans mémoire. Les étapes ne sont pas des fenêtres strictement comparables. La somme RSS n’est pas une somme de pages uniques et le coût des processus ps de mesure est exclu. Le coordinateur/générateur, le broker embarqué et le serveur1414 ne sont pas inclus dans ces colonnes.</p><p>Dans l’état croisé initial, chaque nœud conserve deux documents de maison : environ14,5Mio d’allocations vivantes par nœud sur cette représentation. Le cas sans copie conserve environ7,7 et6,9Mio, chacun pour sa propre maison. Ces chiffres illustrent le prix du doublage ; ils ne sont pas les coûts du layout compact du cœur ni une prévision de RSS de production.</p></section>
<section class="section"><h2>Règles de reprise</h2><p>Un bail et une époque sont propres à chaque maison. La promotion exige une copie non vide, la bonne époque, la bonne séquence et la même empreinte. Une pause de réponse n’est pas une preuve de mort : le fencing du banc est l’arrêt et la récolte d’un processus qu’il détient. Sans témoin, cette preuve est indispensable.</p><p>Les copies reprennent les sorties et leurs horodatages ; aucun journal de réplication n’est écrit sur disque. File RAM :256deltas/1Mio maximum. Instantanés :8Mio par maison, application atomique après contrôleSHA-256 ; morceaux de2048octets, messagesMQTT≤4096octets. La file de reçus d’effets est bornée sans éviction silencieuse et survit à une promotion dans la session de test.</p><p>Une reprise distante conserve la lecture de toute la maison mais reçoit seulement la portée cloud, sur geste humain. Les radios et le réseau local ne deviennent pas disponibles parce qu’un rôle change. Les workflows et effets du banc sont factices : <strong>zéro ordre physique</strong>.</p></section>
<section class="section"><h2>Ce qui reste à qualifier</h2><p>Ce sont de vrais processus locaux et un vrai transport MQTT de test, avec un témoin central dans le coordinateur. Ils ne prouvent pas le consensus distribué ni la survie à la perte de ce coordinateur. Le déploiement sur plusieurs machines, le VPN/TLS, les horloges indépendantes, le stockage de reprise, le coffre, la garde et les exécuteurs de production restent distincts. Aucun HA n’a été arrêté pour simuler une panne.</p><p>L’interface de simulation expose les deux maisons et les contrôles du banc. Les canaux physiques vivants continuent à relever de la passerelle existante. La réception réelle par WebSocket authentifié a confirmé les deux maisons et leurs dix-sept pièces respectives ; les effectifs publiés et ceux des structures brutes sont distingués dans les preuves, sans revendiquer une parité physique exhaustive. <a href="../../../../tools/ha-multihome-poc/README.md">Configuration, protocole et reproduction</a>.</p></section></main></div></body></html>'''
network_path=OUT/'ha-multimaison-tcp.json'
if network_path.exists():
 network=json.loads(network_path.read_text())
 rows=[]
 for case in network['cases']:
  checks=case['checks']
  rows.append(['TCP fermé' if case['case']=='tcp_closed' else 'TCP ouvert, silencieux',esc(case['status']),str(round(case['fault_ms']/1000,2))+' s',str(case['local_steps_during_fault'])+' pas par maison',str(case['link_during']['forwarded_bytes']-case['link_fault_settled']['forwarded_bytes']),str(case['link_during']['active_connections']),str(case['reconnect_ms'])+' ms',str(case['recovery_ms'])+' ms'])
 section='<section class="section" id="perte-connexion-tcp"><h2>Ajout : perte de connexion TCP entre les copies</h2><p>Cette campagne coupe un vrai relais TCP de réplication en loopback, puis laisse les sockets ouvertes en bloquant tous les octets dans les deux sens. Le contrôle des maisons primaires et le témoin central du banc restent accessibles. Aucun flag d’isolation logique d’Engine n’est utilisé.</p>'
 section+=table(['Défaut','Résultat','Durée totale','Progression locale','Octets après stabilisation','Flux TCP pendant défaut','Reconnexion','Retour copies identiques'],rows)
 section+='<p>Dans les deux cas, A reste actif pour A et B pour B ; chaque primaire avance et ses effets factices sont admis. Les copies croisées restent au rang et à l’empreinte précédents. Les demandes de mutation distante expirent et leur promotion est refusée. Une connexion TCP encore ouverte ne prouve donc pas la fraîcheur de la copie.</p><p>Au retour, une nouvelle génération de connexion MQTT est exigée pour chaque nœud. Les deux copies rejoignent le rang courant avec la même empreinte. Un compteur indépendant des documents, conservé pendant les instantanés et vérifié après récupération, confirme qu’aucune sonde ayant expiré n’a été appliquée brièvement puis masquée.</p><p>Le mode de transport antérieur est aussi vérifié par un test de compatibilité. La suite de cette campagne locale comptait59tests Rust, dont les contrats de broker réutilisés. Pour sortir du silence TCP, le relais ferme volontairement les anciennes sockets et jette leurs octets en attente. La reprise du trafic sur les mêmes sockets reste à qualifier. Les durées sont celles de ce banc local en debug, pas des RTO entre deux sites réels.</p><p><a href="ha-multimaison-tcp.json">Résultats TCP</a> · <a href="ha-multimaison-tcp-protocole.md">Protocole et critères</a> · <a href="ha-multimaison-tcp-preuves.json">Preuves courantes</a> · <a href="ha-multimaison-avant-test-tcp.html">Rapport avant cet ajout</a>.</p></section>'
 page=page.replace('<section class="section"><h2>Ce qui reste à qualifier</h2>',section+'<section class="section"><h2>Ce qui reste à qualifier</h2>',1)
if (OUT/'ha-multimaison-wan.json').exists():
 page=page.replace('<section class="section"><h2>Ce qui reste à qualifier</h2>','<section class="section" id="qualification-wan"><h2>Qualification sur les deux hôtes réels</h2><p><strong>Campagne bloquée avant les coupures.</strong> Sur le réseau réel, le Mac obtient des échos des deux hôtes, mais les connexions directes A → B et B → A expirent sur le port du banc. Le transfert des fichiers échoue aussi. Le mode autonome est préparé et ses contrôles locaux passent ; les pertes temporaires et prolongées entre maisons restent non prouvées. <a href="ha-multimaison-wan.html">Mesures, essais prévus, limites et accès nécessaires</a>.</p></section><section class="section"><h2>Ce qui reste à qualifier</h2>',1)
local_path=OUT/'ha-multimaison-pont-local.json'
if local_path.exists():
 local=json.loads(local_path.read_text())
 if local.get('qualification_120s') and local.get('status')=='PASS':
  notice='<section class="section" id="pont-local-qualifie"><h2>Pannes qualifiées entre deux instances sur le Mac</h2><p><strong>Quatre cas réussis sur deux processus autonomes et deux courtiers locaux :</strong> fermeture TCP8s, silence3s avec les mêmes connexions, arrêt du seul flux B→A8s et silence120s. Les primaires restent actifs chez eux ; leurs copies convergent sans gel après retour du pont. Reprise longue par un instantané de chaque maison ; zéro commande physique. <a href="ha-multimaison-pont-local.html">Résultats, mesures mémoire/CPU et preuves de la campagne demandée</a>.</p></section>'
  page=page.replace('<section class="section"><h2>Le scénario principal</h2>',notice+'<section class="section"><h2>Le scénario principal</h2>',1)
  page=page.replace('La reprise du trafic sur les mêmes sockets reste à qualifier.','La variante autonome à deux courtiers a ensuite qualifié un silence bref avec reprise sur les mêmes connexions ; voir la campagne locale ci-dessus.')
  page=page.replace('<h2>Qualification sur les deux hôtes réels</h2>','<h2>Contrôle interhôtes antérieur</h2>')
  page=page.replace('<strong>Campagne bloquée avant les coupures.</strong>','<strong>Constat historique, hors du périmètre local précisé ensuite.</strong>')
(OUT/'ha-multimaison.html').write_text(page)
print('Rapport HA V6 rendu depuis les mesures.')
